/* Capability check only: fresh owned system-logger session, no providers or
   profiling flags enabled, no workload launched and no token/ACL changes. */
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <evntrace.h>
#include <objbase.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <wchar.h>

typedef struct properties {
    EVENT_TRACE_PROPERTIES p;
    wchar_t name[128];
    wchar_t file[32768];
} properties;

int wmain(int argc, wchar_t **argv) {
    if (argc != 2) return 2;
    properties *value = calloc(1, sizeof(*value));
    if (!value) return 2;
    DWORD length = GetFullPathNameW(argv[1], 32768, value->file, NULL);
    if (!length || length >= 32768 || GetFileAttributesW(value->file) != INVALID_FILE_ATTRIBUTES) {
        free(value); return 2;
    }
    HRESULT guid_status = CoCreateGuid(&value->p.Wnode.Guid);
    if (FAILED(guid_status)) { free(value); return 2; }
    HANDLE token = NULL; DWORD token_error = 0, elevation_error = 0;
    DWORD elevation = 0, required = 0; int profile_present = -1, profile_enabled = -1;
    if (!OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &token)) token_error = GetLastError();
    else {
        GetTokenInformation(token, TokenPrivileges, NULL, 0, &required);
        TOKEN_PRIVILEGES *privileges = malloc(required);
        if (!privileges) token_error = ERROR_OUTOFMEMORY;
        else if (!GetTokenInformation(token, TokenPrivileges, privileges, required, &required)) token_error = GetLastError();
        else {
            LUID target;
            if (!LookupPrivilegeValueW(NULL, SE_SYSTEM_PROFILE_NAME, &target)) token_error = GetLastError();
            else {
                profile_present = profile_enabled = 0;
                for (DWORD i = 0; i < privileges->PrivilegeCount; ++i)
                    if (privileges->Privileges[i].Luid.LowPart == target.LowPart &&
                        privileges->Privileges[i].Luid.HighPart == target.HighPart) {
                        profile_present = 1;
                        profile_enabled = !!(privileges->Privileges[i].Attributes & SE_PRIVILEGE_ENABLED);
                    }
            }
        }
        free(privileges);
        TOKEN_ELEVATION info;
        if (GetTokenInformation(token, TokenElevation, &info, sizeof(info), &required)) elevation = info.TokenIsElevated;
        else elevation_error = GetLastError();
        CloseHandle(token);
    }
    if (swprintf_s(value->name, 128, L"NexaUI R01 SystemIO capability %lu %08lx",
        GetCurrentProcessId(), value->p.Wnode.Guid.Data1) < 0) { free(value); return 2; }
    value->p.Wnode.BufferSize = sizeof(*value);
    value->p.Wnode.ClientContext = 1;
    value->p.Wnode.Flags = WNODE_FLAG_TRACED_GUID;
    value->p.BufferSize = 64; value->p.MinimumBuffers = 2; value->p.MaximumBuffers = 4;
    value->p.MaximumFileSize = 4;
    value->p.LogFileMode = EVENT_TRACE_SYSTEM_LOGGER_MODE | EVENT_TRACE_FILE_MODE_SEQUENTIAL;
    value->p.LoggerNameOffset = (ULONG)offsetof(properties, name);
    value->p.LogFileNameOffset = (ULONG)offsetof(properties, file);
    TRACEHANDLE trace = 0;
    ULONG start = StartTraceW(&trace, value->name, &value->p);
    long stop = -1;
    if (start == ERROR_SUCCESS)
        stop = (long)ControlTraceW(trace, value->name, &value->p, EVENT_TRACE_CONTROL_STOP);
    printf("{\"token_query_error\":%lu,\"elevation_query_error\":%lu,\"elevated\":%lu,"
        "\"system_profile_present\":%d,\"system_profile_enabled\":%d,"
        "\"start_system_logger\":%lu,\"stop_owned_session\":%ld,"
        "\"providers_enabled\":0,\"workload_launched\":false,\"events_lost\":%lu}\n",
        token_error,elevation_error,elevation,profile_present,profile_enabled,start,stop,value->p.EventsLost);
    free(value);
    if (token_error || elevation_error) return 1;
    if (start == ERROR_ACCESS_DENIED || start == ERROR_PRIVILEGE_NOT_HELD) return 77;
    return start || stop ? 1 : 0;
}
